for name, rule in changes.items():
    p=Path(name); raw=p.read_text()
    assert hashlib.sha256(raw.encode()).hexdigest()==rule['old'], f'Unexpected base: {name}'
    for start,end,value in reversed(rule['edits']): raw=raw[:start]+value+raw[end:]
    assert hashlib.sha256(raw.encode()).hexdigest()==rule['new'], f'Invalid reconstruction: {name}'
    p.write_text(raw)
print('Applied exact reviewed changes to', len(changes), 'files')
